        b.pin_miso = -1;
        b.pin_dc = Board::dc;
        bus.config(b);
        panel.setBus(&bus);
        auto c = panel.config();
        c.pin_cs = Board::cs;
        c.pin_rst = Board::reset;
        c.pin_busy = -1;
        c.panel_width = 240;
        c.panel_height = 320;
        c.memory_width = 240;
        c.memory_height = 320;
        c.offset_x = 0;
        c.offset_y = 0;
        c.offset_rotation = 0;
        c.dummy_read_pixel = 8;
        c.dummy_read_bits = 1;
        c.readable = false;
        c.invert = false;
        c.rgb_order = false;
        c.dlen_16bit = false;
        c.bus_shared = false;
        panel.config(c);
        if (Board::backlight >= 0) {
            auto l = light.config();
            l.pin_bl = Board::backlight;
            l.invert = false;
            l.freq = 44100;
            l.pwm_channel = 7;
            light.config(l);
            panel.setLight(&light);
        }
